def main():
    with urlopen(DEVTOOLS_URL, timeout=10) as response:
        target = next(item for item in json.load(response) if item.get("type") == "page")
    socket = websocket.create_connection(target["webSocketDebuggerUrl"], timeout=20, suppress_origin=True)
    desktop = verify(socket, 1)
    command(socket, "Emulation.setDeviceMetricsOverride", {"width": 375, "height": 812, "deviceScaleFactor": 1, "mobile": True}, 400)
    mobile = verify(socket, 500)
    command(socket, "Emulation.clearDeviceMetricsOverride", {}, 900)
    print(json.dumps({"track_review_filters": "complete", "desktop": desktop, "mobile_375x812": mobile}, indent=2))
    socket.close()


if __name__ == "__main__":
    try:
        main()
    except Exception as error:
        print(f"Track review filters validation failed: {error}", file=sys.stderr)
        sys.exit(1)
